import json, sys
rate = json.load(open('/tmp/oc-632-rate.json'))
assert rate, 'no rate-based rule found on the web ACL'
limit, window = rate[0]
problems = []
if window not in (60, 120, 300, 600):
    problems.append(f'evaluation window {window} is not an allowed value')
thr = open('/tmp/oc-632-thr.txt').read().strip()
try:
    api_rate = float(thr)
except ValueError:
    api_rate = None
    problems.append(f'API throttlingRateLimit is unreadable ({thr!r}); the '
                    'effective per-client ceiling cannot be computed')
if api_rate is not None and api_rate <= 0:
    problems.append(f'API throttlingRateLimit is {api_rate}, so the stage is '
                    'either unthrottled or fully closed')
if api_rate is not None and window:
    waf_rps = float(limit) / float(window)
    print(f'api_rate={api_rate} waf={limit}/{window}s={waf_rps:.2f}rps '
          f'effective_per_source_ip={min(api_rate, waf_rps):.2f}rps')
cfg = json.load(open('/tmp/oc-632-log.json')).get('LoggingConfiguration') or {}
if not cfg:
    problems.append('WAF logging is not configured')
else:
    lf = cfg.get('LoggingFilter') or {}
    filters = lf.get('Filters') or []
    if not filters:
        problems.append('no LoggingFilter.Filters: every request is logged')
    default = lf.get('DefaultBehavior')
    if default != 'DROP':
        problems.append(f'LoggingFilter.DefaultBehavior is {default!r}, not DROP')
    for i, f in enumerate(filters):
        if f.get('Behavior') != 'KEEP':
            problems.append(f'filter[{i}].Behavior is {f.get("Behavior")!r}')
        acts = [ (c.get('ActionCondition') or {}).get('Action')
                 for c in (f.get('Conditions') or []) ]
        if not acts:
            problems.append(f'filter[{i}] has no ActionCondition')
        elif set(acts) != {'BLOCK'}:
            problems.append(f'filter[{i}] keeps {sorted(set(acts))}, not BLOCK only')
    red = json.dumps(cfg.get('RedactedFields') or [])
    if 'api-key' not in red.lower():
        problems.append('the api key header is not redacted; keys would land in logs')
print('limit', limit, 'window', window, 'problems', problems)
sys.exit(1 if problems else 0)
OCEOF

