import ast, sys
sys.dont_write_bytecode = True
SRC = 'lambda/api/services/egress_admin_service.py'
tree = ast.parse(open(SRC, encoding='utf-8').read())
defs = {n.name: n for n in ast.walk(tree)
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
ENTRY = '_build_extra_allow'
if ENTRY not in defs:
    print(f'FAIL {ENTRY} is gone; the admission path has no entry point')
    sys.exit(1)

# The admission SURFACE: the entry point plus every module-local function reachable from it. #668
# moved the per-entry guards into _admit_allow_entry, so asserting they sit inside the entry function
# would fail on a refactor that kept every guard intact.
surface, seen, queue = [], set(), [ENTRY]
while queue:
    name = queue.pop()
    if name in seen or name not in defs:
        continue
    seen.add(name)
    node = defs[name]
    surface.append(name)
    for n in ast.walk(node):
        if isinstance(n, ast.Call):
            callee = n.func.id if isinstance(n.func, ast.Name) else \
                     (n.func.attr if isinstance(n.func, ast.Attribute) else '')
            if callee in defs:
                queue.append(callee)
print('admission surface:', sorted(surface))
text = '\n'.join(ast.unparse(defs[n]) for n in surface)

problems = []
if '_resolve_spire_server_ip' in defs:
    problems.append('_resolve_spire_server_ip is still defined')
for n in surface:
    for node in ast.walk(defs[n]):
        if isinstance(node, ast.Compare) and '8081' in ast.unparse(node):
            problems.append(f'8081 is still special-cased in {n}(): {ast.unparse(node)[:80]}')
if 'SPIRE' in text:
    problems.append('the admission surface still references SPIRE')
for needed in ('_EXTRA_ALLOW_REDLINE_PORTS', '_IMDS', 'prefixlen', 'min_prefix'):
    if needed not in text:
        problems.append(f'generic guard {needed} is absent from the whole admission surface '
                        f'{sorted(surface)}')
if problems:
    print('FAIL')
    for p in problems: print('  -', p)
    sys.exit(1)
print('PASS no 8081 branch anywhere on the admission surface, and all four generic guards are '
      'present somewhere on it')
OCEOF

