import hashlib, json, pathlib, sys
m = json.load(open('manifest.json'))
# Every path that declares a shipped artifact, not only the patch/** ones — there are zero of those
# (each patch/** entry is INERT_METADATA with a null artifact), which made this check vacuous.
rows = [(p, v) for p, v in m['paths'].items() if v.get('artifact')]
missing, mismatched = [], []
for p, v in rows:
    f = pathlib.Path(v['artifact'])
    if not f.is_file():
        missing.append((p, v['artifact'])); continue
    if hashlib.sha256(f.read_bytes()).hexdigest() != v['patch_sha256']:
        mismatched.append(p)
print('artifacts declared', len(rows), '| missing', len(missing), '| hash mismatch', len(mismatched))
for p, a in missing: print('   MISSING', p, '->', a)
for p in mismatched: print('   MISMATCH', p)
if not rows:
    print('FAIL no artifact-bearing path at all: this check would pass vacuously')
    sys.exit(1)
if missing or mismatched:
    sys.exit(1)
print('PASS every declared artifact is present and its bytes match patch_sha256')
OCEOF
